// These constants represent the RISC-V ELF and the image ID generated by risc0-build.
// The ELF is used for proving and the ID is used for verification.
use cli_serde::load_elf;
use risc0_zkvm::sha::{Digest, Digestible};
use risc0_zkvm::{
    default_prover, get_prover_server, ExecutorEnv, Groth16Receipt,
    Groth16ReceiptVerifierParameters, InnerReceipt, ProverOpts, Receipt,
};

pub fn serialize_receipt(receipt: Receipt, name: &str) -> Result<(), String> {
    //serialize with bincode
    let receipt_bytes = bincode::serialize(&receipt).map_err(|_| "Failed to serialize receipt")?;
    //save to file
    let path = std::path::Path::new(name);
    std::fs::write(path, receipt_bytes)
        .map_err(|_| format!("Failed to write receipt to file: {}", name))?;

    Ok(())
}

pub fn deserialize_receipt(name: &str) -> Receipt {
    //deserialize receipt from file using bin code
    let path = std::path::Path::new(name);
    let receipt_bytes = std::fs::read(path).unwrap();
    let receipt: Receipt = bincode::deserialize(&receipt_bytes).unwrap();
    receipt
}

pub fn prove_stark(input: &str, elf_path: &str, output_file: &str) -> Result<(), String> {
    let input_parsed = std::fs::read(input)
        .map_err(|e| format!("Failed to read input file: {}", e))?;
    let start = std::time::Instant::now();

    let env = ExecutorEnv::builder()
        .write(&input_parsed)
        .map_err(|e| format!("Failed to write input: {}", e))?
        .build()
        .map_err(|e| format!("Failed to build environment: {}", e))?;

    // Obtain the default prover.
    let prover = default_prover();

    let elf = load_elf(elf_path).map_err(|e| format!("Failed to load ELF file: {}", e))?;

    // Proof information by proving the specified ELF binary.
    // This struct contains the receipt along with statistics about execution of the guest
    let prove_info = prover
        .prove(env, &elf)
        .map_err(|e| format!("Failed to prove: {}", e))?;

    let duration = start.elapsed();

    // extract the receipt.
    let receipt = prove_info.receipt;

    serialize_receipt(receipt, output_file)?;
    println!(
        "The proof was executed, and the receipt saved to the file: {}. Total time: {:?}",
        output_file, duration
    );

    Ok(())
}

pub fn verify_stark(image_id: impl Into<Digest>, receipt_fname: &str) -> Result<(), String> {
    let receipt = deserialize_receipt(receipt_fname);
    receipt.verify(image_id)
        .map_err(|e| format!("Failed to verify receipt: {}", e))?;

    Ok(())
}

pub fn prove_snark(receipt_fname: &str) -> Result<(Vec<u8>, Vec<u8>), String> {
    let receipt = deserialize_receipt(receipt_fname);
    let journal = receipt.journal.bytes.clone();

    let groth16_receipt = get_prover_server(&ProverOpts::groth16())
        .map_err(|e| format!("Failed to get prover server: {}", e))?
        .compress(&ProverOpts::groth16(), &receipt)
        .map_err(|e| format!("Failed to compress receipt: {}", e))?;

    let mut data_vec = Vec::new();
    for data in &groth16_receipt
        .inner
        .groth16()
        .map_err(|e| format!("Failed to get groth16 data: {}", e))?
        .seal
    {
        data_vec.push(*data);
    }

    Ok((data_vec, journal))
}

/// Proves the guest and compresses the proof into a single succinct receipt, so the recursion (lift and join of every
/// segment) runs with the prover of this build: on the GPU in the cuda build. `prove_snark` turns that receipt into a
/// groth16 proof without repeating the recursion.
///
/// With `p254_seal_file`, it also runs the identity_p254 step and writes its seal, which `wrap_groth16` turns into a
/// groth16 proof with only the final wrap left to do.
pub fn prove_succinct(
    input: &str,
    elf_path: &str,
    output_file: &str,
    p254_seal_file: Option<&str>,
) -> Result<(), String> {
    let input_parsed =
        std::fs::read(input).map_err(|e| format!("Failed to read input file: {}", e))?;
    let elf = load_elf(elf_path).map_err(|e| format!("Failed to load ELF file: {}", e))?;
    let env = ExecutorEnv::builder()
        .write(&input_parsed)
        .map_err(|e| format!("Failed to write input: {}", e))?
        .build()
        .map_err(|e| format!("Failed to build environment: {}", e))?;

    let start = std::time::Instant::now();
    let composite = default_prover()
        .prove(env, &elf)
        .map_err(|e| format!("Failed to prove: {}", e))?
        .receipt;
    println!("Stark proof time: {:?}", start.elapsed());

    let prover = get_prover_server(&ProverOpts::succinct())
        .map_err(|e| format!("Failed to get prover server: {}", e))?;

    let start = std::time::Instant::now();
    let succinct = prover
        .compress(&ProverOpts::succinct(), &composite)
        .map_err(|e| format!("Failed to compress receipt: {}", e))?;
    println!("Recursion time: {:?}", start.elapsed());

    if let Some(p254_seal_file) = p254_seal_file {
        let start = std::time::Instant::now();
        let p254 = prover
            .identity_p254(
                succinct
                    .inner
                    .succinct()
                    .map_err(|e| format!("Failed to get succinct receipt: {}", e))?,
            )
            .map_err(|e| format!("Failed to run identity_p254: {}", e))?;
        std::fs::write(p254_seal_file, p254.get_seal_bytes())
            .map_err(|e| format!("Failed to write file {}: {}", p254_seal_file, e))?;
        println!("identity_p254 time: {:?}", start.elapsed());
    }

    serialize_receipt(succinct, output_file)
}

/// Turns the identity_p254 seal written by `prove_succinct` into a groth16 proof of the claim of its succinct receipt
/// (with the docker prover in the cpu build), and checks the proof before returning its seal and the journal.
pub fn wrap_groth16(
    receipt_fname: &str,
    p254_seal_fname: &str,
) -> Result<(Vec<u8>, Vec<u8>), String> {
    let receipt = deserialize_receipt(receipt_fname);
    let succinct = receipt
        .inner
        .succinct()
        .map_err(|e| format!("Failed to get succinct receipt: {}", e))?;
    let p254_seal = std::fs::read(p254_seal_fname)
        .map_err(|e| format!("Failed to read file {}: {}", p254_seal_fname, e))?;

    let start = std::time::Instant::now();
    let seal = risc0_groth16::prove::shrink_wrap(&p254_seal)
        .map_err(|e| format!("Failed to wrap the seal: {}", e))?
        .to_vec();
    println!("Groth16 wrap time: {:?}", start.elapsed());

    let groth16 = InnerReceipt::Groth16(Groth16Receipt::new(
        seal.clone(),
        succinct.claim.clone(),
        Groth16ReceiptVerifierParameters::default().digest(),
    ));
    groth16
        .verify_integrity_with_context(&Default::default())
        .map_err(|e| format!("The groth16 proof does not verify: {}", e))?;

    Ok((seal, receipt.journal.bytes))
}
